namespace:
/** An expression */
type Expr =
  | { kind: "number"; value: number }
  | { kind: "add"; left: Expr; right: Expr }
  | { kind: "if"; condition: Expr; then: Expr; else: Expr };

type EnumWithCommonFields =
  | {
      success: false;
      /** x coordinate */ x: integer;
      /** y coordinate */ y: number;
      /** z coordinate */
      z: string;
    }
  | { success: true; /** x coordinate */ x: integer; y: number; z: integer };

interface Schema {
  e: EnumWithCommonFields;
}
interface String {}
interface Boolean {}
interface List {}
interface Map {}
interface EncodeDefault {}
interface Serializable {}
interface KindAdd {}
interface AnyHolder {
  any: any;
}
interface SerializerHolder {
  serializer: any;
}
interface Square {
  kind: "square";
  size: number;
  fromJson: string;
  self: string;
  foo: "foo";
}

type E = "class" | "if" | "foo-BAR";

type Matrix = {
  kind: "matrix";
  matrix: Square[][];
  otherMatrix?: Square[][];
  foo?: { [x: string]: Square[] };
  ints: integer[];
  init: boolean;
  encode: boolean;
};

type MatrixUnion =
  | Matrix
  | {
      kind: "empty";
      init: boolean;
      encode: boolean;
      matrix: Square[][];
      foo: string;
    };

type DiscriminatorCodingKeys = {};

type CppNameConflicts = {
  index: any;
  std: boolean;
  this: boolean;
  indirect: boolean;
  int32T: integer;
};

type ComplexType = {
  stringField: string;
  intField: integer;
  numField: number;
  boolField: boolean;
  literalField: "constant";
  enumField: E;
  stringUnion: "foo-bar" | "zooKar";
  unionField: Expr;
  structField: Square;
  stringList: string[];
  structList: Square[];
  matrix: integer[][];
  mapField: { [x: string]: integer };
  optString?: string;
  optInt?: integer;
  optNum?: number;
  optBool?: boolean;
  optEnum?: E;
  optStringUnion?: "foo-bar" | "zooKar";
  optUnion?: Expr;
  optStruct?: Square;
  optStringList?: string[];
  optStructList?: Square[];
  optMatrix?: integer[][];
  optMap?: { [x: string]: integer };
};
